namespace ghidra.feature.vt.gui.filters;







public class IntegerInputVerifier : InputVerifier {

    /* @Override */
    public bool verify( JComponent input ) {
        if ( !(input is JFormattedTextField) ) {
            return true;
        }

        JFormattedTextField ftf = (JFormattedTextField)input;
        AbstractFormatter formatter = ftf.getFormatter();
        if ( formatter == null ) {
            return true;
        }

        string text = ftf.getText();
        try {       
            Integer intValue = ((Number) formatter.stringToValue(text)).intValue();
            if ( intValue.compareTo( 0 ) < 0 ) {
                // no negatives or values over 1
                return false;
            }

            return true;
        }
        catch ( ParseException e ) {
            return false;
        }
    }

    /** Overridden to beep when the user tries to click out of the edited field when invalid */
    /* @Override */
    public bool shouldYieldFocus( JComponent input ) {
        bool shouldYieldFocus = base.shouldYieldFocus( input );
        if ( !shouldYieldFocus ) {
            warn();
        }
        return shouldYieldFocus;
    }

    private void warn() {
        Toolkit.getDefaultToolkit().beep();
    }
}
